import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function SamplesInput() {
  const [count, setCount] = useState("");
  const navigate = useNavigate();

  const handleNext = () => {
    if (!count || count <= 0) {
      alert("الرجاء إدخال عدد العينات أولاً!");
      return;
    }
    navigate("/features");
  };

  return (
    <div className="samples-container">
      <h1 className="samples-title">إدخال عدد العينات الطبية</h1>
      <p className="samples-description">
        الرجاء إدخال عدد العينات الطبية التي سيتم تحليلها في هذا المشروع.
      </p>

      <div className="samples-input-box">
        <label>عدد العينات:</label>
        <input
          type="number"
          min="1"
          value={count}
          onChange={(e) => setCount(e.target.value)}
        />
      </div>

      <div className="samples-buttons">
        <button onClick={() => navigate("/")} className="btn-back">
          رجوع
        </button>
        <button onClick={handleNext} className="btn-next">
          التالي
        </button>
      </div>
    </div>
  );
}

export default SamplesInput;
